<?php
require_once __DIR__ . '/includes/auth.php';
$token = trim($_GET['token'] ?? $_POST['token'] ?? ''); $error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $password = $_POST['password'] ?? ''; $statement = db()->prepare('SELECT id FROM users WHERE reset_token = ? AND reset_expires_at > NOW()'); $statement->execute([$token]); if (!$statement->fetch() || strlen($password) < 6) $error = 'Token inválido ou senha muito curta.'; else { $statement = db()->prepare('UPDATE users SET password = ?, reset_token = NULL, reset_expires_at = NULL WHERE reset_token = ?'); $statement->execute([password_hash($password, PASSWORD_DEFAULT), $token]); flash('success', 'Senha alterada. Faça login.'); redirect('login.php'); } }
$pageTitle = 'Nova senha'; require __DIR__ . '/partials/header.php'; ?><div class="auth-shell"><div class="panel"><h1 class="page-title h3">Defina uma nova senha</h1><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post" data-validate novalidate><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="token" value="<?= e($token) ?>"><label class="form-label">Nova senha</label><input class="form-control mb-3" type="password" name="password" required minlength="6"><button class="btn btn-primary w-100">Salvar senha</button></form></div></div><?php require __DIR__ . '/partials/footer.php'; ?>
